/// Returns 1.0 if `i == j`, otherwise returns 0.0.
fn diag_val(i: usize, j: usize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Constructs an `n x n` identity matrix of `f64`
///
/// # Arguments
///
/// * `n` – the dimension of the square identity matrix
///
/// # Returns
///
/// A vector of `n` rows, each of which is a vector of `n` `f64` values,
/// where the diagonal entries are 1.0 and all off-diagonal entries are 0.0.
fn identity(n: usize) -> Vec<Vec<f64>> {
    // Pre-allocate the outer vector with capacity `n`
    let mut mat = Vec::with_capacity(n);
    for i in 0..n {
        // For each row, pre-allocate a vector of length `n`
        let mut row = Vec::with_capacity(n);
        for j in 0..n {
            row.push(diag_val(i, j));
        }
        mat.push(row);
    }
    mat
}

